export const getGetVehicleHistoryUrl = (id: string,
    params?: GetVehicleHistoryParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : value.toString())
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/vehicles/${id}/history?${stringifiedParams}` : `/api/vehicles/${id}/history`
}

